// ===== p91 : textures réelles dans la vue personnage (ambientCG, CC0) — sol, écorce, feuillage, paille, torchis, basalte =====
// Les images sont réduites à 512 px (WebP) ; elles se multiplient aux couleurs du terrain, qui gardent la nuance des étages de l'île.
const TEX91={"sol": "data:image/webp;base64,", "feuille": "data:image/webp;base64,", "ecorce": "data:image/webp;base64,", "paille": "data:image/webp;base64,", "basalte": "data:image/webp;base64,", "torchis": "data:image/webp;base64,"};
const TXC91={};function tx91(k,r){const key=k+'|'+r;if(TXC91[key])return TXC91[key];const t=new THREE.TextureLoader().load(TEX91[k]);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(r,r);try{t.anisotropy=4}catch(e){}return TXC91[key]=t}
function vpTextures(){const V=VP;if(!V||V.tex91)return;V.tex91=1;
 V.sc.traverse(o=>{if(!o.isMesh||!o.material||Array.isArray(o.material))return;const g=o.geometry,p=g&&g.parameters||{},m=o.material,ty=g&&g.type;
  if(ty==='PlaneGeometry'&&p.width>=150&&m.vertexColors){m.map=tx91('sol',38);m.needsUpdate=true}
  else if(ty==='CylinderGeometry'&&o.isInstancedMesh){m.map=tx91('ecorce',1);m.color.setHex(0xc8b098);m.needsUpdate=true}
  else if(ty==='IcosahedronGeometry'&&o.isInstancedMesh){m.map=tx91('feuille',1);m.needsUpdate=true}
  else if(ty==='BoxGeometry'&&p.width===2.4){m.map=tx91('torchis',1);m.color.setHex(0xffffff);m.needsUpdate=true}
  else if(ty==='ConeGeometry'&&p.radius===2){m.map=tx91('paille',1);m.color.setHex(0xe8d4a0);m.needsUpdate=true}
  else if(ty==='DodecahedronGeometry'){m.map=tx91('basalte',1);m.color.setHex(0xffffff);m.needsUpdate=true}
  else if(ty==='IcosahedronGeometry'&&p.radius===.8&&!o.isInstancedMesh){m.map=tx91('feuille',1);m.needsUpdate=true}})}
{const vb=vpBoucle;vpBoucle=function(){vb.apply(this,arguments);try{if(VP&&VP.p84&&!VP.tex91)vpTextures()}catch(e){console.warn(e)}}}
